  [CH("Two views", "Pike, 1954", [("Emic", "The insider's categories", "Emic"), ("Etic", "The observer's categories", "Etic")],
      "A: Emic accounts use the insider's own categories. | B: Etic accounts use the observer's, for comparison."),
   CH("Fieldwork tools", "Classic", [("Participant observation", "Live with the people", "Participant"), ("Genealogical method", "Rivers, 1910", "Genealogical")],
      "A: Participant observation means living with the people. | B: The genealogical method, from W. H. R. Rivers, maps kin to understand society."),
   QT("Others", "Case study, interview, schedule and questionnaire.",
      "A: Add case studies, interviews, | B: schedules and questionnaires.")],
