E(157, "mendel-hardy", "anthro1-13", P, "Pea plants explained inheritance", "Human genetics: Mendel and Hardy–Weinberg", "dna",
  ["Gregor Mendel (1866)", "G. H. Hardy and Wilhelm Weinberg (1908)"],
  "A: The laws of inheritance were found in a monastery garden. | B: With pea plants.",
  [TL("Milestones", [(1866, "Mendel publishes", "1866"), (1908, "Hardy–Weinberg", "1908")],
      "A: Gregor Mendel published his pea experiments in 1866. | B: In 1908, Hardy and Weinberg described populations in genetic balance."),
   CH("Mendel's laws", "Two", [("Segregation", "Each parent passes one allele", "Segregation"), ("Independent assortment", "Traits sort independently", "Independent")],
      "A: Segregation: each parent passes on one allele for a trait. | B: Independent assortment: different traits sort independently."),
   QT("Hardy–Weinberg", "Allele frequencies stay constant unless something changes them.",
      "A: Allele frequencies stay the same across generations | B: unless mutation, selection, migration or drift change them.")],
  QZ("Which force does NOT disturb Hardy–Weinberg equilibrium?", ["Mutation", "Natural selection", "Random mating", "Migration"], 2,
     "Right. Random mating is an assumption of the equilibrium, not a force against it.", "A: Your turn. | B: Which one doesn't disturb it?"))

E(158, "race-variation", "anthro1-14", P, "Most human variation is within groups, not between them", "Race and biological variation", "people",
  ["UNESCO, Statement on Race (1950)", "Richard Lewontin, 'The Apportionment of Human Diversity' (1972)"],
  "A: Are human races biologically real? | B: Genetics says the picture is more complicated.",
  [TL("Turning points", [(1950, "UNESCO Statement on Race", "1950"), (1972, "Lewontin's study", "1972")],
      "A: In 1950, UNESCO issued its first statement on race. | B: In 1972, Richard Lewontin measured where genetic variation lies."),
   ST("Lewontin", [(85, "%", "of variation is within populations", "85")],
      "A: He found about 85 percent of genetic variation is within populations, | B: and only a small share between so-called races."),
   QT("Clines", "Traits change gradually across space, not in sharp blocks.",
      "A: Traits like skin colour change gradually across space. | B: Anthropologists call these clines. Racism has no biological basis.")],
  QZ("Lewontin found that most human genetic variation lies:", ["Between races", "Within populations", "Only in Africa", "In blood groups only"], 1,
     "Right. Within populations.", "A: Your turn. | B: Where does most variation lie?"))

